package com.codexgui.service;

import com.codexgui.i18n.Messages;

import java.nio.file.Path;

/** Local references must be text in the model prompt; app-server mentions are metadata. */
public final class FileReferenceText {
    private static final String PREFIX = Messages.message("\n[引用文件] ");

    private FileReferenceText() { }

    public static String format(Path path) {
        return PREFIX + path.toAbsolutePath().normalize() + "\n";
    }

    /** Only recognize complete reference input items generated by format, not arbitrary user prose. */
    public static String parse(String text) {
        if (text == null || !text.startsWith(PREFIX) || !text.endsWith("\n")) return null;
        var path = text.substring(PREFIX.length(), text.length() - 1);
        if (path.isBlank() || path.indexOf('\n') >= 0 || path.indexOf('\r') >= 0) return null;
        try { return Path.of(path).isAbsolute() ? path : null; }
        catch (RuntimeException ignored) { return null; }
    }
}
